package UserDao;
use strict;
use warnings;

# Look up a user by name.
sub get_user {
    my ($dbh, $name) = @_;
    return $dbh->selectall_arrayref("SELECT id, name FROM users WHERE name = '$name'");
}

1;

use strict;
use warnings;
use Test::More;
use UserDao;

{
    package FakeDbh;
    sub new { bless {}, shift }
    sub selectall_arrayref { return [[1, 'alice']] }
}

subtest returns_rows => sub {
    is_deeply(UserDao::get_user(FakeDbh->new, 'alice'), [[1, 'alice']], 'rows');
};

done_testing;
